local function holding_dragon(ctx,self)for _,e in ipairs(ctx:hand(ctx:controller(self)))do local d=ctx:card_definition(ctx:entity(e).card_id);for _,t in ipairs(d.tags or{})do if t=="dragon"or t=="all"then return true end end end return false end
local card={api_version=1,id="LOOT_528",name="Twilight Acolyte",text="<b>Battlecry:</b> If you're holding a Dragon, swap this minion's Attack with another minion's.",set="LOOTAPALOOZA",type="minion",class="priest",rarity="epic",cost=3,attack=2,health=4,keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx,self)if not holding_dragon(ctx,self)then return{}end;local r={};for _,e in ipairs(ctx:minions())do if e~=self then r[#r+1]=e end end;return r end}
function card.on_battlecry(ctx,self,target)if target then local a,b=ctx:entity(self).attack,ctx:entity(target).attack;ctx:modify_all({self},{attack=b,operation="final_set",silenciable=true});ctx:modify_all({target},{attack=a,operation="final_set",silenciable=true})end end
return card
